import { Text, View, ViewStyle } from 'react-native'
import { SignUpButton } from './SignUpButton'
import { Image } from 'expo-image'
import { Mail } from 'lucide-react-native'
import { router } from 'expo-router'
import { useGoogleOAuth } from '../hooks/useGoogleOAuth'
import { defineStyles } from '@/utils/defineStyles'
import { useAppleOAuth } from '../hooks/useAppleOAuth'

interface SignUpButtonContainerProps {
	appleLoginButtonStyle: ViewStyle
	googleLoginButtonStyle: ViewStyle
	emailLoginButtonStyle: ViewStyle
}

export const SignUpButtonContainer = ({
	appleLoginButtonStyle,
	googleLoginButtonStyle,
	emailLoginButtonStyle
}: SignUpButtonContainerProps) => {
	const signInWithGoogle = useGoogleOAuth()
	const signInWithApple = useAppleOAuth()
	return (
		<View style={styles.authContainer}>
			<SignUpButton
				variant="dark"
				animatedStyle={googleLoginButtonStyle}
				onPress={signInWithGoogle}
				label="Continue with Google"
				iconComponent={
					<Image
						source={{ uri: 'google-logo' }}
						style={styles.googleIcon}
						contentFit="contain"
					/>
				}
			/>
			<SignUpButton
				variant="light"
				animatedStyle={appleLoginButtonStyle}
				onPress={signInWithApple}
				label="Continue with Apple"
				iconComponent={<Text style={styles.appleIcon}></Text>}
			/>
			<SignUpButton
				variant="white"
				animatedStyle={emailLoginButtonStyle}
				onPress={() => {
					router.push('/enter-email')
				}}
				label="Continue with Email"
				iconComponent={<Mail size={18} color="#000" />}
			/>
		</View>
	)
}

const styles = defineStyles({
	authContainer: {
		position: 'absolute',
		bottom: 40,
		left: 20,
		right: 20,
		justifyContent: 'center',
		alignItems: 'center',
		gap: 20
	},
	appleIcon: {
		fontSize: 24,
		color: '#000'
	},
	googleIcon: {
		width: 30,
		height: 30,
		marginHorizontal: -6
	}
})
